using System.Globalization;

foreach (var t in Tokenize("12 + 3.5*(x - 4)")) Console.Write($"{t} | ");

List<Token> Tokenize(ReadOnlySpan<char> text)
{
    var tokens = new List<Token>();
    return tokens;
}

enum TokenKind { Number, Name, Plus, Minus, Star, Slash, LParen, RParen }

record struct Token(TokenKind Kind, double Number = 0, string? Name = null);
